#include <omp.h>
#include <vector>
#include <cstddef>

double productWithInverses(std::vector<double> const& x) {
    // Empty product is 1.0
    double product = 1.0;
    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(x.size());

    #pragma omp parallel for reduction(*:product)
    for (std::ptrdiff_t i = 0; i < n; ++i) {
        const double value = x[static_cast<std::size_t>(i)];
        const double factor = (i & 1) ? (1.0 / value) : value;
        product *= factor;
    }

    return product;
}
