#include <omp.h>
#include <vector>
#include <cstddef>

double productWithInverses(std::vector<double> const& x) {
    const std::ptrdiff_t n = static_cast<std::ptrdiff_t>(x.size());
    if (n == 0) {
        return 1.0;
    }

    // Compute each per-index factor in parallel, then multiply them
    // serially in a fixed left-to-right order for deterministic results
    // under every thread count.
    std::vector<double> factors(static_cast<std::size_t>(n));

    #pragma omp parallel for schedule(static)
    for (std::ptrdiff_t i = 0; i < n; ++i) {
        const double v = x[static_cast<std::size_t>(i)];
        factors[static_cast<std::size_t>(i)] = (i & 1) ? (1.0 / v) : v;
    }

    double product = 1.0;
    for (std::ptrdiff_t i = 0; i < n; ++i) {
        product *= factors[static_cast<std::size_t>(i)];
    }

    return product;
}
